css:
@page {
    size: A4;
    margin: 0;
}

.print-format {
    margin: 0 !important;
    padding: 0 !important;
}

body {
    margin: 0 !important;
    padding: 0 !important;
}

.label-sheet {
    width: 8.27in;
    height: 11.69in;
    display: grid;
    grid-template-columns: repeat(3, 2.688in);
    grid-template-rows: repeat(6, 2in);
    page-break-inside: avoid;
    column-gap: 0;
    row-gap: 0.18in;
    padding-left: 0.12in;
    padding-top: 0.25in;
    justify-content: start !important;
    align-content: start !important;

    margin: 0 !important;
    box-sizing: border-box;
}

.label {
    width: 2.68in;
    height: 2in;
    padding: 0.01in;
    box-sizing: border-box;

    font-size: 12px;
    border: 1px solid #000;
}

/* Typography */
.label h1 {
    font-size: 12px;
    text-align: center;
    margin: 0;
}

.label h3 {
    font-size: 10px;
    text-align: center;
    margin: 2px 0;
}

.label p {
    margin: 8px 0;
    font-size: 11px;
    line-height: 1.2;
}

.label hr {
    margin: 2px 0;
}

html:
{% if doc.docstatus != 1 %}
    <h3>Document must be submitted to print</h3>
{% else %}
<div class="label-sheet">

{% set total = (doc.no_of_container or 0) | int %}
{% set per_page = 15 %}

{% for i in range(total) %}

{% if i > 0 and i % per_page == 0 %}
        </div>
        <div style="page-break-before: always;"></div>
        <div class="label-sheet">
    {% endif %}

<div class="label">
    <h1>BHARAT STERILE PRIVATE LIMITED</h1>
     
    <hr>

    <p><b>Batch Number:</b> {{ doc.manufacturing_batch }}</p>
    <p><b>Product Name:</b> {{ doc.item }}</p>
    <p><b>Manufacturing Date:</b> {{ doc.manufacturing_date }}</p>
    <p><b>Expiry Date:</b> {{ doc.expiry_date }}</p>

    <p><b>Container No:</b> {{ i + 1 }}/{{ total }}</p>

    <hr>
</div>

{% endfor %}

</div>
{% endif %}

